// ignore_for_file: unused_element, unnecessary_cast

/// Dataproc job config.
class JobPlacementResponse {
  /// Optional. Cluster labels to identify a cluster where the job will be submitted.
  final Map<String, String> clusterLabels;

  /// The name of the cluster where the job will be submitted.
  final String clusterName;

  /// A cluster UUID generated by the Dataproc service when the job is submitted.
  final String clusterUuid;

  /// Creates a new [JobPlacementResponse].
  /// [clusterLabels] Optional. Cluster labels to identify a cluster where the job will be submitted.
  /// [clusterName] The name of the cluster where the job will be submitted.
  /// [clusterUuid] A cluster UUID generated by the Dataproc service when the job is submitted.
  JobPlacementResponse({
    required this.clusterLabels,
    required this.clusterName,
    required this.clusterUuid,
  });

  Map<String, dynamic> toMap() {
    final map = <String, dynamic>{};
    map['clusterLabels'] = clusterLabels;
    map['clusterName'] = clusterName;
    map['clusterUuid'] = clusterUuid;
    return map;
  }

  factory JobPlacementResponse.fromMap(Map<String, dynamic> map) {
    return JobPlacementResponse(
      clusterLabels: (map['clusterLabels'] as Map).cast<String, String>(),
      clusterName: map['clusterName'] as String,
      clusterUuid: map['clusterUuid'] as String,
    );
  }
}
